# Successive discount formula
def total_discount(d1, d2):
    return d1 + d2 - (d1 * d2 / 100)
print("20% + 10% discount:", total_discount(20, 10)) # 28%

import React, { useState } from "react";
export function Counter() {
    const [count, setCount] = useState(0);
    return <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>;
}

import { useState, useEffect } from "react";
export function useOnlineStatus() {
    const [online, setOnline] = useState(true);
    useEffect(() => {
        const handle = () => setOnline(navigator.onLine);
        window.addEventListener("online", handle);
        window.addEventListener("offline", handle);
        return () => { window.removeEventListener("online", handle); window.removeEventListener("offline", handle); };
    }, []);
    return online;
}

import numpy as np
def cosine_sim(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))
resume_emb = np.array([0.1, 0.9, 0.4])
job_emb = np.array([0.15, 0.85, 0.38])
print("Match:", round(cosine_sim(resume_emb, job_emb) * 100, 2), "%")

