function isValid(s) {
    const stack = [];
    const map = { ")": "(", "}": "{", "]": "[" };
    for (const c of s) {
        if (map[c]) {
            if (stack.pop() !== map[c]) return false;
        } else {
            stack.push(c);
        }
    }
    return stack.length === 0;
}

